#include <iostream>
#include <string>

struct TrieNode {
    TrieNode* children[26] = {};  // one per letter, nullptr when missing
    bool isEnd = false;           // whether a word ends at this node
};

class Trie {
public:
    void insert(const std::string& word) {
        TrieNode* node = &root_;
        for (char ch : word) {
            int i = ch - 'a';
            if (node->children[i] == nullptr) {
                node->children[i] = new TrieNode();
            }
            node = node->children[i];
        }
        node->isEnd = true;
    }

    bool search(const std::string& word) {
        TrieNode* node = find(word);
        return node != nullptr && node->isEnd;
    }

    bool startsWith(const std::string& prefix) {
        return find(prefix) != nullptr;
    }

private:
    TrieNode root_;

    // The node at the end of prefix, or nullptr when no word starts with it.
    TrieNode* find(const std::string& prefix) {
        TrieNode* node = &root_;
        for (char ch : prefix) {
            node = node->children[ch - 'a'];
            if (node == nullptr) {
                return nullptr;
            }
        }
        return node;
    }
};

