package main

import "fmt"

// TrieNode has a child for each letter (nil when missing) and marks where a
// word ends.
type TrieNode struct {
	children [26]*TrieNode
	isEnd    bool
}

// Trie stores words letter by letter, down from its root.
type Trie struct {
	root TrieNode
}

func (t *Trie) insert(word string) {
	node := &t.root
	for _, ch := range word {
		i := ch - 'a'
		if node.children[i] == nil {
			node.children[i] = &TrieNode{}
		}
		node = node.children[i]
	}
	node.isEnd = true
}

// find returns the node at the end of prefix, or nil when no word starts with it.
func (t *Trie) find(prefix string) *TrieNode {
	node := &t.root
	for _, ch := range prefix {
		node = node.children[ch-'a']
		if node == nil {
			return nil
		}
	}
	return node
}

func (t *Trie) search(word string) bool {
	node := t.find(word)
	return node != nil && node.isEnd
}

func (t *Trie) startsWith(prefix string) bool {
	return t.find(prefix) != nil
}

func main() {
	var q int
	fmt.Scan(&q)
	trie := Trie{}
	for i := 0; i < q; i++ {
		var op, word string
		fmt.Scan(&op, &word)
		switch op {
		case "insert":
			trie.insert(word)
		case "search":
			fmt.Println(trie.search(word))
		case "startsWith":
			fmt.Println(trie.startsWith(word))
		}
	}
}

